class Solution {
  public int wordSlipsPeakTicket(String line, int k) {
    String a=line; List<Integer> out=new ArrayList<>();
    {int len=0;for(int i=0;i<=a.length();i++){if(i==a.length()||a.charAt(i)==' '){if(len>0)out.add(len);len=0;}else len++;}}
    int answer=out.isEmpty()?0:out.get(0);for(int x:out)answer=Math.max(answer,x);return answer;
